function getPriority(waitMinutes) {
  if (waitMinutes >= 60) return '긴급';
  else if (waitMinutes >= 30) return '우선';
  else return '일반';
}

function getCrowdLevel(minutes) {
  if (minutes >= 30) return '혼잡';
  else if (minutes >= 10) return '보통';
  return '여유';
}

function getDiscount(countInput) {
  const count = Number(countInput);
  if (count >= 10) return 2000;
  else if (count >= 5) return 1000;
  return 0;
}
